## 3. Result-Generation Logic (form data → recommendation)

Source: `client/src/lib/womensHealthLogic.ts`

```typescript
/**
 * Women's Health Compass Scoring Logic
 * Pelvic Congestion Syndrome / Pelvic Venous Disorder (PeVD) Assessment
 *
 * This scoring system synthesizes diagnostic criteria from multiple evidence-based
 * sources for Pelvic Congestion Syndrome / Pelvic Venous Disorders (PeVD).
 */

export interface SymptomData {
  chronicPelvicPain: boolean;
  painDuration: string; // months
  painLocation: 'left' | 'right' | 'bilateral' | '';
  exacerbatedByStanding: boolean;
  postcoitalPain: boolean;
  premenstrualWorsening: boolean;
  vulvarVaricosities: boolean;
  gravidity: string;
  parity: string;
}

export interface HemodynamicData {
  lovDiameter: string; // mm
  rovDiameter: string; // mm
  lovRefluxDuration: string; // ms
  rovRefluxDuration: string; // ms
  crossPelvicFlow: 'absent' | 'present' | '';
  nutcrackerAngle: string; // degrees
}

export interface AnatomyData {
  pelvicVaricosities: boolean;
  uterineVeinDilation: boolean;
  dilatedArcuateVeins: 'none' | 'mild' | 'pronounced' | '';
  mayThurner: boolean;
}

export interface AssessmentData {
  symptoms: SymptomData;
  hemodynamics: HemodynamicData;
  anatomy: AnatomyData;
}

export interface RecommendationResult {
  congestionScore: number;
  confidence: 'low' | 'moderate' | 'high';
  lovIncompetence: 'detected' | 'inconclusive' | 'absent';
  nutcrackerRisk: 'detected' | 'inconclusive' | 'absent';
  pelvicVaricosities: 'confirmed' | 'suspected' | 'absent';
  recommendation: string;
  treatmentOptions: string[];
  label: string;
  summary: string;
  color: 'primary' | 'warning' | 'destructive';
  score: number;
  criteriaMetCount: number;
  criteriaTotalCount: number;
}

export function computePeVDScore(data: AssessmentData): RecommendationResult {
  let score = 0;
  const maxScore = 10;
  let criteriaMetCount = 0;
  const criteriaTotalCount = 10;

  // ── Symptom scoring ──────────────────────────────────────────────
  // Chronic pelvic pain >6 months is the hallmark presentation
  if (data.symptoms.chronicPelvicPain) {
    score += 1;
    criteriaMetCount++;
  }

  // Orthostatic exacerbation is characteristic of venous etiology
  if (data.symptoms.exacerbatedByStanding) {
    score += 1;
    criteriaMetCount++;
  }

  // Postcoital pain/dyspareunia strongly associated with PCS
  if (data.symptoms.postcoitalPain) {
    score += 1;
    criteriaMetCount++;
  }

  // Vulvar varicosities are a specific exam finding
  if (data.symptoms.vulvarVaricosities) {
    score += 0.5;
  }

  // Premenstrual worsening reflects hormonal influence on venous tone
  if (data.symptoms.premenstrualWorsening) {
    score += 0.5;
  }

  // Multiparity (≥2) is a significant risk factor
  if (parseInt(data.symptoms.gravidity) >= 2) {
    score += 0.5;
    criteriaMetCount++;
  }

  // ── Hemodynamic scoring ──────────────────────────────────────────
  // Ovarian vein diameter thresholds:
  //   ≥5mm = suggestive, ≥6mm = diagnostic threshold, ≥8mm = severe
  const lovDiam = parseFloat(data.hemodynamics.lovDiameter);
  if (!isNaN(lovDiam)) {
    if (lovDiam >= 8) {
      score += 2;
      criteriaMetCount++;
    } else if (lovDiam >= 6) {
      score += 1.5;
      criteriaMetCount++;
    } else if (lovDiam >= 5) {
      score += 0.5;
    }
  }

  // Reflux duration >1 second on Valsalva = pathological
  const lovReflux = parseFloat(data.hemodynamics.lovRefluxDuration);
  if (!isNaN(lovReflux) && lovReflux > 1000) {
    score += 1;
    criteriaMetCount++;
  }

  // Cross-pelvic collateral flow indicates advanced incompetence
  if (data.hemodynamics.crossPelvicFlow === 'present') {
    score += 1;
    criteriaMetCount++;
  }

  // ── Anatomy scoring ──────────────────────────────────────────────
  // Pelvic varicosities confirmed on imaging
  if (data.anatomy.pelvicVaricosities) {
    score += 1;
    criteriaMetCount++;
  }

  // Dilated arcuate veins traversing myometrium
  if (data.anatomy.dilatedArcuateVeins === 'pronounced') {
    score += 0.5;
    criteriaMetCount++;
  } else if (data.anatomy.dilatedArcuateVeins === 'mild') {
    score += 0.25;
  }

  const normalized = Math.min(score / maxScore, 1);

  // ── LOV incompetence assessment ──────────────────────────────────
  // Combined diameter + reflux criteria
  const lovIncompetence: RecommendationResult['lovIncompetence'] =
    lovDiam >= 6 && lovReflux > 1000
      ? 'detected'
      : lovDiam >= 5 || lovReflux > 500
        ? 'inconclusive'
        : 'absent';

  // ── Nutcracker assessment ────────────────────────────────────────
  // Aortomesenteric angle <25° strongly suggests Nutcracker
  // Angle 25–35° is borderline
  const nutAngle = parseFloat(data.hemodynamics.nutcrackerAngle);
  const nutcrackerRisk: RecommendationResult['nutcrackerRisk'] =
    !isNaN(nutAngle) && nutAngle < 25
      ? 'detected'
      : !isNaN(nutAngle) && nutAngle < 35
        ? 'inconclusive'
        : 'absent';

  const pelvicVaricosities: RecommendationResult['pelvicVaricosities'] =
    data.anatomy.pelvicVaricosities
      ? 'confirmed'
      : data.anatomy.dilatedArcuateVeins !== 'none' &&
          data.anatomy.dilatedArcuateVeins !== ''
        ? 'suspected'
        : 'absent';

  const confidence: RecommendationResult['confidence'] =
    normalized >= 0.7 ? 'high' : normalized >= 0.4 ? 'moderate' : 'low';

  let recommendation = '';
  const treatmentOptions: string[] = [];
  let label = '';
  let color: 'primary' | 'warning' | 'destructive' = 'destructive';

  if (normalized >= 0.7) {
    label = 'Criteria Met for PeVD';
    color = 'primary';
    recommendation = `Criteria met for Pelvic Venous Disorder (PeVD; formerly termed Pelvic Congestion Syndrome). ${
      lovIncompetence === 'detected'
        ? 'Left Ovarian Vein embolization is clinically indicated based on current hemodynamic profile.'
        : 'Further venographic confirmation recommended before intervention.'
    }`;
    treatmentOptions.push('Ovarian vein embolization');
    treatmentOptions.push('Sclerotherapy');
    if (nutcrackerRisk === 'detected')
      treatmentOptions.push('Renal vein stenting (Nutcracker)');
  } else if (normalized >= 0.4) {
    label = 'Moderate Suspicion for PeVD';
    color = 'warning';
    recommendation =
      'Moderate suspicion for Pelvic Venous Disorder (PeVD). Consider diagnostic venography with provocation maneuvers for definitive assessment.';
    treatmentOptions.push('Diagnostic venography');
    treatmentOptions.push('MR venography');
    treatmentOptions.push('Conservative management trial');
  } else {
    label = 'Low Probability for PeVD';
    color = 'destructive';
    recommendation =
      'Low probability for Pelvic Venous Disorder (PeVD) based on current data. Consider alternative differential diagnoses including endometriosis, adenomyosis, or musculoskeletal etiologies.';
    treatmentOptions.push('Expanded differential workup');
    treatmentOptions.push('Pelvic MRI');
  }

  return {
    congestionScore: normalized,
    confidence,
    lovIncompetence,
    nutcrackerRisk,
    pelvicVaricosities,
    recommendation,
    treatmentOptions,
    label,
    summary: recommendation,
    color,
    score: Math.round(normalized * 100),
    criteriaMetCount,
    criteriaTotalCount,
  };
}
